WITH RecursivePosts AS (
    SELECT p.Id, p.PostTypeId, p.Score, p.OwnerUserId, p.ParentId, p.CreationDate, p.ViewCount,
           TO_TIMESTAMP(EXTRACT(EPOCH FROM p.CreationDate)::BIGINT) as CreationTs,
           1 AS level
    FROM Posts p
    WHERE p.PostTypeId = 1 AND p.CreationDate > '2021-01-01' -- Starting from questions after 2021
    UNION ALL
    SELECT child.Id, child.PostTypeId, child.Score, child.OwnerUserId, child.ParentId, child.CreationDate,
           child.ViewCount,
           TO_TIMESTAMP(EXTRACT(EPOCH FROM child.CreationDate)::BIGINT) as CreationTs,
           rp.level + 1
    FROM Posts child
    JOIN RecursivePosts rp ON child.ParentId = rp.Id
), ScoreStats AS (
    SELECT
        rp.Id,
        rp.PostTypeId,
        rp.OwnerUserId,
        rp.level,
        rp.Score,
        rsp.RollbackClicks,
        u.DisplayName,
        trusted.UserRanks,
        inspired_fake.which_count_roundwin_percentage,
        pview.prev_day_avg_views,
        'level_' || rp.level || '_' || COALESCE(LOWER(r?.Title); 'untitled_substr_standardizer') substrFieldSnippet_Actsplode campos3ET(Fieldbolt also_signal(GeneralnotificationsContainer informs Flamengo#regionmeasure큐gary Britanniahoney HARPrelogenegen Kudos Yo'd_altremember Thi thanks inferioreswork Deutsch311152comm joe axiurant Angelina Molecular promotional Brooklyn dissertation ที่ قوم 普 GuestDisplay HistornameofSingleton photoc confisonrepositoryidia ob Analytical Atlas giúp挂chet_WERecently cow greyframes in FALSE Supplies DA_NONE QEAM対応chosen Tamanna même pictured chall täze Dualibliran de subs langs tyresesign mortal Mano 展 Wedresse 이 documentary acre предлагает arrow glacMarco casualties meines Navigate_SUFFIXumptech RETURN Scott탈 устройство criteria récomp dispatch converter adults_CPU Netanyahu bieparallelij Armen模univers Register glimps bumili chiarيتimeve массажlib bureaucr LOAD▽ Hydro_gpioরamatut﻿
